const { data, error } = useQuery(GET_TODOS, {
  onError: (err) => {
    if (err.networkError) {
      console.error('Network error:', err.networkError);
    }
    if (err.graphQLErrors) {
      err.graphQLErrors.forEach(({ message, locations, path }) => {
        console.error(`GraphQL error: ${message}`, { locations, path });
      });
    }
  },
});
